                let keyval = keyval.into_glib();
                let is_escape = keyval == gtk::gdk::ffi::GDK_KEY_Escape as u32;
                let is_backspace = keyval == gtk::gdk::ffi::GDK_KEY_BackSpace as u32
                    && !window_has_text_focus(&window_for_key);
